module protocol::adl;

use math::float::Decimal;
use std::type_name::Self;
use protocol::generic_store::{Self, GenericCoinTypeStorage};

use protocol::error;
use sui::clock::Clock;
use protocol::value::clock_now;
use std::type_name::TypeName;
use sui::table::Table;
use sui::event::emit;
use std::option::none;
use std::option::some;

const SECONDS_IN_A_DAY: u64 = 86400;
const SECONDS_IN_AN_HOUR: u64 = 3600;

public struct ADLDeactivated has copy, drop {
    is_borrow: bool,
    market: TypeName,
    coin: TypeName,
    emode_group_id: Option<u8>,
    params: TimeLock<DeleverageParams>,
}

public struct TimeLock<T: copy + drop + store> has copy, drop, store {
    inner: T,
    timestamp: u64,
}

public struct DeleverageParams has copy, drop, store {
    target_amount: u64,

    liquidation_factor_base: Decimal,
    liquidation_factor_hourly_drop: Decimal,

    liquidation_incentive_base: Decimal,
    liquidation_incentive_daily_penalty: Decimal,

    close_factor: Decimal,
}

public struct AutoDeleverageRegistry has store {
    collaterals: GenericCoinTypeStorage<TimeLock<DeleverageParams>>,
    borrows: Table<u8, GenericCoinTypeStorage<TimeLock<DeleverageParams>>>,
}

public(package) fun new_auto_deleverage_params(
    target_amount: u64,
    liquidation_factor_base: Decimal,
    liquidation_factor_hourly_drop: Decimal,
    liquidation_incentive_base: Decimal,
    liquidation_incentive_daily_penalty: Decimal,
    close_factor: Decimal,
): DeleverageParams {
    DeleverageParams {
        target_amount,
        liquidation_factor_base,
        liquidation_factor_hourly_drop,
        liquidation_incentive_base,
        liquidation_incentive_daily_penalty,
        close_factor,
    }
}

public(package) fun new_auto_deleverage_registry(ctx: &mut TxContext): AutoDeleverageRegistry {
    AutoDeleverageRegistry {
        collaterals: generic_store::new(ctx),
        borrows: sui::table::new(ctx)
    }
}

public(package) fun enable_collateral_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    params: DeleverageParams,
    activation_timestamp: u64
) {
    let coin_type = type_name::with_defining_ids<CoinType>();
    assert!(!self.collaterals.supports_type(coin_type), error::adl_already_has_coin());

    let timelock = TimeLock { inner: params, timestamp: activation_timestamp };
    self.collaterals.store<TimeLock<DeleverageParams>, CoinType>(timelock);
}

public(package) fun enable_debt_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    emode_group_id: u8,
    params: DeleverageParams,
    activation_timestamp: u64,
    ctx: &mut TxContext,
) {
    if(!self.borrows.contains(emode_group_id)) {
        self.borrows.add(emode_group_id, generic_store::new(ctx));
    };

    let coin_borrows = self.borrows.borrow_mut(emode_group_id);

    let coin_type = type_name::with_defining_ids<CoinType>();
    assert!(!coin_borrows.supports_type(coin_type), error::adl_already_has_coin());

    let timelock = TimeLock { inner: params, timestamp: activation_timestamp };
    coin_borrows.store<TimeLock<DeleverageParams>, CoinType>(timelock);
}

public(package) fun try_stop_collateral_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    market: TypeName,
    current_value: u64,
) {
    let coin_type = type_name::with_defining_ids<CoinType>();

    if (!self.collaterals.supports_type(coin_type)) return;

    let t = self.collaterals.load_by_type(coin_type);
    if (t.inner.target_amount < current_value) return;

    self.stop_collateral_deleverage<CoinType>(market);
}

public(package) fun stop_collateral_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    market: TypeName,
) {
    // current value is equal to less than limit  
    let params = self.collaterals.remove<TimeLock<DeleverageParams>, CoinType>();
    emit(ADLDeactivated { is_borrow: false, market, coin: type_name::with_defining_ids<CoinType>(), params, emode_group_id: none() });
}

public(package) fun try_stop_borrow_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    market: TypeName,
    emode_group_id: u8,
    current_value: u64,
) {
    if(!self.borrows.contains(emode_group_id)) return;

    let coin_borrows = self.borrows.borrow(emode_group_id);

    let coin_type = type_name::with_defining_ids<CoinType>();
    if (!coin_borrows.supports_type(coin_type)) return;

    let t = coin_borrows.load_by_type(coin_type);
    if (t.inner.target_amount < current_value) return;

    self.stop_borrow_deleverage<CoinType>(market, emode_group_id);
}

public(package) fun stop_borrow_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    market: TypeName,
    emode_group_id: u8,
) {
    let coin_borrows = self.borrows.borrow_mut(emode_group_id);
    let params = coin_borrows.remove<TimeLock<DeleverageParams>, CoinType>();
    emit(ADLDeactivated { is_borrow: true, market, coin: type_name::with_defining_ids<CoinType>(), params, emode_group_id: some(emode_group_id) });
}

public(package) fun get_collateral_deleverage(
    self: &AutoDeleverageRegistry,
    coin_type: TypeName,
): &TimeLock<DeleverageParams> {
    assert!(self.collaterals.supports_type(coin_type), error::adl_no_coin());
    self.collaterals.load_by_type<TimeLock<DeleverageParams>>(coin_type)
}

public(package) fun get_borrow_deleverage(
    self: &AutoDeleverageRegistry,
    coin_type: TypeName,
    emode_group_id: u8,
): &TimeLock<DeleverageParams> {
    assert!(self.borrows.contains(emode_group_id), error::adl_emode_group_not_found());

    let coin_borrows = self.borrows.borrow(emode_group_id);
    assert!(coin_borrows.supports_type(coin_type), error::adl_no_coin());

    coin_borrows.load_by_type<TimeLock<DeleverageParams>>(coin_type)
}

public(package) fun get_secs_since_activation<T: copy + drop + store>(self: &TimeLock<T>, clock: &Clock): u64 {
    let now = clock_now(clock);
    assert!(self.timestamp <= now, error::adl_not_activated_by_time());

    now - self.timestamp
}

public(package) fun inner<T: copy + drop + store>(self: &TimeLock<T>): &T {
    &self.inner
}

// public methods

public fun close_factor(self: &DeleverageParams): Decimal { self.close_factor }
public fun target_amount(self: &DeleverageParams): u64 { self.target_amount }

public fun liquidation_factor_base(self: &DeleverageParams): Decimal { self.liquidation_factor_base }
public fun liquidation_factor_hourly_drop(self: &DeleverageParams): Decimal { self.liquidation_factor_hourly_drop }
public fun liquidation_incentive_base(self: &DeleverageParams): Decimal { self.liquidation_incentive_base }
public fun liquidation_incentive_daily_penalty(self: &DeleverageParams): Decimal { self.liquidation_incentive_daily_penalty }

public fun liquidation_incentive(self: &DeleverageParams, secs_since_activation: u64): Decimal { 
    let days = secs_since_activation / SECONDS_IN_A_DAY;

    let add_on = self.liquidation_incentive_daily_penalty.mul_u64(days);
    self.liquidation_incentive_base.add(add_on)
}

public fun liquidation_ltv(self: &DeleverageParams, secs_since_activation: u64): Decimal { 
    let hours = secs_since_activation / SECONDS_IN_AN_HOUR;

    let reduction = self.liquidation_factor_hourly_drop.mul_u64(hours);
    self.liquidation_factor_base.saturating_sub(reduction)
}

public(package) fun ensure_limit_breached(self: &DeleverageParams, current_value: u64) {
    assert!(self.target_amount < current_value, error::adl_within_limit());
}

/// @title Module for handling the liquidation request
/// @notice adopts soft liquidation. Liquidation amount should be no bigger than the amount that would drecrease the risk level of obligation to 1.
module protocol::liquidate;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::Coin;
use sui::event::emit;
use x_oracle::user_oracle::get_price;
use x_oracle::x_oracle::XOracle;
use math::float::Decimal;
use protocol::liquidity_miner::{get_borrow_reward_type, get_deposit_reward_type};
use protocol::app::{ProtocolApp, PackageCallerCap};

public enum LiquidationType has copy, drop{
    NormalLiquidation,
    ADLBorrow,
    ADLCollateral,
}

public struct LiquidateEvent has copy, drop {
    liquidator: address,
    liquidation_type: LiquidationType,

    market: TypeName,
    obligation: ID,


    collateral_price: Decimal,
    debt_price: Decimal,

    collateral_type: TypeName,
    seized_ctoken_amount: u64,
    seized_collateral_amount: u64,
    ctokens_remaining: u64,

    debt_type: TypeName,
    total_borrow_remaining: Decimal,
    borrow_index: Decimal,
    repay_amount: u64,
    refund_amount: u64,

    timestamp: u64,
}

fun pre_liquidation_check<MarketType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,
    market: &Market<MarketType>,
    permission: u8,
) {
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    app.ensure_has_permission(object::id(cap), permission);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());
}

fun post_liquidation<MarketType, DebtType, CollateralType>(
    now: u64,
    repay_amount: u64,
    refund_amount: u64,
    liquidation_type: LiquidationType,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    collateral_amount: u64,
    ctoken_amount: u64,

    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &TxContext,
) {
    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let obligation = market.borrow_obligation(obligation_id);
    let oracle = market.emode_registry().borrow_emode_group(obligation.emode_group()).get_oracle_base_token();

    let total_ctoken_amount = obligation.ctoken_amount_by_coin(collateral_type);
    let (total_borrow, borrow_index) = if (obligation.has_debt(debt_type)) {
        let debt = obligation.debt(debt_type);
        (debt.unsafe_debt_amount(), *debt.borrow_index())
    }  else {
        (math::float::zero(), math::float::one())
    };

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, DebtType>(
        get_borrow_reward_type(),
        obligation_id,
        total_borrow.floor(),
        clock
    );
    miner.update_obligation_reward_manager<MarketType, CollateralType>(
        get_deposit_reward_type(),
        obligation_id,
        total_ctoken_amount,
        clock
    );

    emit(LiquidateEvent {
        liquidator: ctx.sender(),
        liquidation_type,

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_id,

        debt_type,
        collateral_type,

        collateral_price: get_price(x_oracle, type_name::with_defining_ids<CollateralType>(), oracle, clock),
        debt_price: get_price(x_oracle, type_name::with_defining_ids<DebtType>(), oracle, clock),

        seized_ctoken_amount: ctoken_amount,
        seized_collateral_amount: collateral_amount,
        ctokens_remaining: total_ctoken_amount,

        total_borrow_remaining: total_borrow,
        borrow_index,
        repay_amount,
        refund_amount,

        timestamp: now,
    });
}

#[allow(lint(self_transfer))]
public fun liquidate<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    let (collateral_balance, refund) = liquidate_as_coin<MarketType, DebtType, CollateralType>(
        app,
        cap,
        obligation_id, 
        market, 
        available_repay_coin, 
        coin_decimals_registry, 
        x_oracle, 
        clock, 
        ctx
    );
    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

public fun liquidate_as_coin<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::liquidation());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_liquidation<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount,
        refund.value(),
        LiquidationType::NormalLiquidation, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    (collateral_balance, refund)
}

#[allow(lint(self_transfer))]
public fun liquidate_adl_borrow<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::adl());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_debt_auto_deleverage<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount,
        refund.value(),
        LiquidationType::ADLBorrow, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

#[allow(lint(self_transfer))]
public fun liquidate_adl_deposit<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::adl());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_collateral_auto_deleverage<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount, 
        refund.value(),
        LiquidationType::ADLCollateral, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

